import { useState, type FormEvent } from 'react';
import {
  JxButton,
  JxTextField,
  JxSelect,
  JxSelectItem,
  JxSwitch,
  JxAlert,
} from '@jinx-ui/react';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

type Role = 'viewer' | 'editor' | 'admin';

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState<Role>('viewer');
  const [notify, setNotify] = useState(true);
  const [showSuccess, setShowSuccess] = useState(false);

  const isEmailInvalid = email.length > 0 && !EMAIL_PATTERN.test(email);
  const canSubmit = EMAIL_PATTERN.test(email);

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!canSubmit) {
      return;
    }

    setShowSuccess(true);
    setEmail('');
    setRole('viewer');
    setNotify(true);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4)', maxWidth: '28rem' }}>
      {showSuccess && (
        <JxAlert variant="success" dismissible onDismiss={() => setShowSuccess(false)}>
          Приглашение отправлено.
        </JxAlert>
      )}

      <form
        onSubmit={handleSubmit}
        style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4)' }}
      >
        <JxTextField
          label="Почта"
          type="email"
          value={email}
          onValueChange={setEmail}
          hint="Например, name@company.com"
          error={isEmailInvalid ? 'Похоже, это не адрес почты' : undefined}
          required
        />

        <JxSelect label="Роль" value={role} onValueChange={(value) => setRole(value as Role)}>
          <JxSelectItem value="viewer">Наблюдатель</JxSelectItem>
          <JxSelectItem value="editor">Редактор</JxSelectItem>
          <JxSelectItem value="admin">Администратор</JxSelectItem>
        </JxSelect>

        <JxSwitch label="Отправить уведомление" value={notify} onValueChange={setNotify} />

        <JxButton type="submit" variant="primary" disabled={!canSubmit}>
          Отправить приглашение
        </JxButton>
      </form>
    </div>
  );
}

